2. **RetryStrategy.kt**:
```kotlin
class RetryStrategy(private val config: OutboxConfig) {
    fun calculateDelay(attempt: Int): Long {
        // Exponential backoff: base_delay * 2^attempt with jitter
        val exponentialDelay = config.retryBaseDelayMs * (1 shl attempt)
        val jitter = (0..(exponentialDelay / 4)).random()
        return (exponentialDelay + jitter).coerceAtMost(60_000L) // Max 1 minute
    }

    fun shouldRetry(attempt: Int, maxAttempts: Int): Boolean = attempt < maxAttempts
}
