```kotlin
class RabbitConsumer(
    private val connection: RabbitConnection,
    private val inboxRepository: InboxRepository,
    private val extractor: IdempotencyExtractor,
    private val config: RabbitConsumerConfig
) {
    private val scope = CoroutineScope(Dispatchers.IO + SupervisorJob())
    private var running = true
    private var channel: Channel? = null

    suspend fun start() {
        channel = connection.getChannel().apply {
            basicQos(config.prefetchCount)
        }

        val consumer = object : DefaultConsumer(channel) {
            override fun handleDelivery(
                consumerTag: String,
                envelope: Envelope,
                properties: AMQP.BasicProperties,
                body: ByteArray
            ) {
                scope.launch {
                    try {
                        val payload = Json.parseToJsonElement(body.toString(Charsets.UTF_8))

                        // Extract idempotency key from header or payload
                        val idempotencyKey = properties.headers?.get("x-idempotency-key")?.toString()
                            ?: extractor.extract(payload, config.idempotencyKeyPath).getOrNull()
                            ?: properties.messageId
                            ?: UUID.randomUUID().toString()

                        val message = InboxMessage(
                            source = config.sourceName,
                            idempotencyKey = idempotencyKey,
                            eventType = properties.headers?.get("x-event-type")?.toString(),
                            payload = payload
                        )

                        when (inboxRepository.store(message)) {
                            is InboxResult.Stored, is InboxResult.Duplicate -> {
                                // Ack after successful store or duplicate detection
                                channel?.basicAck(envelope.deliveryTag, false)
                            }
                            is InboxResult.Error -> {
                                // Nack and requeue on storage failure
                                channel?.basicNack(envelope.deliveryTag, false, true)
                            }
                        }
                    } catch (e: Exception) {
                        logger.error("Failed to process message", e)
                        channel?.basicNack(envelope.deliveryTag, false, true)
                    }
                }
            }
        }

        channel?.basicConsume(config.queueName, false, consumer)
    }

    suspend fun stop() {
        running = false
        scope.cancel()
        channel?.close()
    }
}

